#!/usr/bin/env python3
"""Plan/replay only the explicitly selected, recorded CT campaign.

Default is read-only planning. --run delegates sequential bounded groups to the
qualified archived-pin controller. --force is the sole recomputation request.
"""
from __future__ import annotations
import argparse,hashlib,importlib.util,json,math,os,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

class ReplayError(ValueError):pass

def read_json(path):
    try:return json.loads(path.read_text())
    except (OSError,ValueError) as error:raise ReplayError(f'Missing/unreadable required record {path}: {error}') from error

def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda:stream.read(1024*1024),b''):h.update(block)
    return h.hexdigest()

def within(root,value):
    value=Path(value)
    path=(value if value.is_absolute() else root/value).resolve()
    if not path.is_relative_to(root):raise ReplayError('Replay record must be inside the copied codex directory: '+str(value))
    return path

def selected_names(selection):
    reference=selection.get('reference_case')
    if not isinstance(reference,str) or not reference.startswith('ct'):raise ReplayError('An explicit selected CT reference_case is required; no GLM or priority fallback is used')
    animation=selection.get('animation_case')
    if animation is not None and (not isinstance(animation,str) or not animation.startswith('ct')):raise ReplayError('animation_case must explicitly name a CT case')
    if 'required_case_names' in selection:
        names=selection['required_case_names']
        if not isinstance(names,list) or not names:raise ReplayError('required_case_names must be a nonempty explicit list')
        if len(set(names))!=len(names):raise ReplayError('required_case_names contains duplicates')
        for name in [reference,animation]:
            if name and name not in names:raise ReplayError('required_case_names omits selected case '+name)
    else:
        names=[reference]+([animation] if animation else [])
        for category,pairs in selection.items():
            if not category.endswith('_comparisons'):continue
            if not isinstance(pairs,list):raise ReplayError(category+' must be a list of case pairs')
            for pair in pairs:
                if not isinstance(pair,(list,tuple)) or len(pair)!=2 or not all(isinstance(x,str) for x in pair):raise ReplayError('Malformed case pair in '+category)
                names.extend(pair)
        names=list(dict.fromkeys(names))
    for name in names:
        if not isinstance(name,str) or not name.startswith('ct') or Path(name).name!=name or name in ['.','..']:raise ReplayError('Only explicit local CT case names are accepted: '+str(name))
    return names

def load_controller(root):
    path=root/'scripts/run_ct_simulations.py'
    spec=importlib.util.spec_from_file_location('ct_replay_controller',path)
    if spec is None or spec.loader is None:raise ReplayError('Cannot import archived-pin CT controller')
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
    return module

def inspect_case(root,name,controller,metadata,hash_cache):
    """Read ROOT receipts and canonical helpers only; never materialize a pin."""
    if name not in controller.CASES:raise ReplayError('Case absent from current qualified controller catalogue: '+name)
    folder=root/'results'/name
    paths={key:folder/filename for key,filename in [('selection','code_selection.json'),('usage','runner_usage.json'),('metadata','metadata.json'),('status','candidate_status.json'),('provenance','input_code_provenance.json')]}
    records={key:read_json(path) for key,path in paths.items()}
    cfg_path=folder/'run.cfg';native_path=folder/'athinput.ct'
    if not cfg_path.is_file() or not native_path.is_file():raise ReplayError(name+': matching canonical run.cfg and athinput.ct are required')
    cfg=controller.readcfg(cfg_path);code=records['selection'];usage=records['usage']
    receipt_sha=code.get('code_receipt_sha256','')
    if len(receipt_sha)!=64 or any(c not in '0123456789abcdef' for c in receipt_sha):raise ReplayError(name+': invalid archived receipt SHA')
    pin_dir=root/'solver/athena_ct_pins'/receipt_sha
    receipt_path=pin_dir/'code_receipt.json';receipt=read_json(receipt_path)
    binary=within(root,code.get('binary',''))
    if binary!=pin_dir/'athena' or digest(receipt_path)!=receipt_sha:raise ReplayError(name+': archived pin path/receipt digest disagrees')
    if not binary.is_file() or digest(binary)!=code.get('binary_sha256') or code['binary_sha256']!=receipt.get('executable_sha256'):raise ReplayError(name+': portable archived binary hash disagrees')
    # All recorded input/source paths are ROOT-relative archived copies. Original
    # absolute source and /tmp names in the code receipt are never opened here.
    provenance=records['provenance']
    if not isinstance(provenance,dict) or not provenance:raise ReplayError(name+': empty input/source provenance')
    for filename,expected in provenance.items():
        if Path(filename).is_absolute():raise ReplayError(name+': provenance must use ROOT-relative archived paths')
        path=within(root,filename)
        if path not in hash_cache:hash_cache[path]=digest(path)
        if hash_cache[path]!=expected:raise ReplayError(name+': recorded input/source hash mismatch: '+filename)
    for path in [cfg_path,native_path,*paths.values()]:
        if path==paths['status'] or path==paths['usage'] or path==paths['provenance']:continue
        key=str(path.relative_to(root))
        if key not in provenance:raise ReplayError(name+': canonical record is not covered by input provenance: '+key)
    execution=code.get('execution_selection',{})
    threads=int(cfg['threads']);blocks=int(cfg.get('ct_radial_blocks',1))
    if threads not in [1,2,4] or blocks not in [1,2,4,8] or threads>blocks:raise ReplayError(name+': unsupported recorded thread/block settings')
    if execution!=dict(threads=threads,radial_blocks=blocks):raise ReplayError(name+': code_selection execution settings differ from run.cfg')
    if int(usage.get('threads',-1))!=threads or int(usage.get('radial_meshblocks',1))!=blocks:raise ReplayError(name+': runner thread/block receipt differs from canonical configuration')
    if code.get('missing_capabilities'):raise ReplayError(name+': recorded code lacks required capabilities')
    extras=receipt.get('extras',{});runtime=dict(extras.get('runtime_config',{}));runtime.update(extras.get('required_runtime_config',{}));runtime_env=dict(extras.get('runtime_env',{}))
    if runtime!=code.get('runtime_config',{}) or runtime_env!=code.get('runtime_env',{}):raise ReplayError(name+': code-selection runtime flags/env differ from frozen receipt')
    pin=dict(binary=binary,receipt=receipt_path,receipt_sha256=receipt_sha,tracked=[],capabilities=set(code.get('capabilities',[])),runtime_config=runtime,runtime_env=runtime_env,extras=extras,execution_selection=execution)
    input_receipts=[]
    for relative in code.get('input_capability_receipts',[]):
        path=within(root,relative)
        if not path.is_file():raise ReplayError(name+': missing recorded input capability receipt '+relative)
        input_receipts.append(str(path.relative_to(root)))
    movie=int(cfg.get('ecliptic_slice_pixels',0))>0
    controller.select_movies(pin,[name] if movie else [])
    if movie and not code.get('movie_selection'):raise ReplayError(name+': movie config lacks its recorded coordinate/basis selection')
    wanted,required=controller.settings(name,metadata,pin,folder)
    if required-pin['capabilities']:raise ReplayError(name+': current case requires capabilities absent from recorded code')
    if cfg_path.read_text()!=controller.cfgtext(wanted):raise ReplayError(name+': current canonical config differs from recorded run.cfg; no settings are inferred or replaced')
    if native_path.read_text()!=controller.native_input(wanted,folder):raise ReplayError(name+': current native input differs from recorded athinput.ct')
    controller.validate_config(wanted,controller.parse_native(native_path.read_text()))
    caps={'cpu_limit':int(usage['CPU_time_cap_s']),'wall_limit':float(usage['wall_limit_s']),'rss_mib':int(usage['process_tree_RSS_cap_MiB']),'as_mib':int(usage['address_space_cap_MiB'])}
    if not(1<=caps['cpu_limit']<=7200 and 1<=caps['wall_limit']<=7200 and 64<=caps['rss_mib']<=2048 and 128<=caps['as_mib']<=4096):raise ReplayError(name+': recorded resource cap is outside the qualified controller bounds')
    concurrency=int(usage['concurrent_case_limit'])
    if concurrency<1:raise ReplayError(name+': invalid recorded concurrency limit')
    complete=controller.completion(folder,wanted)
    recorded_complete=records['status'].get('execution_complete') is True
    reusable=recorded_complete and complete['execution_complete'] and usage.get('exit_code',usage.get('returncode',1))==0 and not usage.get('termination_reason')
    return dict(name=name,folder=str(folder.relative_to(root)),archived_pin=str(pin_dir.relative_to(root)),receipt_sha256=receipt_sha,binary_sha256=code['binary_sha256'],threads=threads,radial_blocks=blocks,resource_caps=caps,recorded_concurrency_limit=concurrency,input_capability_receipts=sorted(input_receipts),movie=movie,runtime_env=runtime_env,execution_complete=reusable,recorded_status=records['status'].get('status'),completion_check=complete,previous_observed_resources={k:usage.get(k) for k in ['wall_seconds_including_inputs','user_seconds','system_seconds','maxrss_kb']},record_sha256={str(path.relative_to(root)):digest(path) for path in [cfg_path,native_path,*paths.values(),receipt_path]},no_original_source_reads=True)

def grouped_jobs(jobs):
    compatible={}
    for job in jobs:
        key=json.dumps({key:job[key] for key in ['archived_pin','threads','radial_blocks','resource_caps','input_capability_receipts','runtime_env','recorded_concurrency_limit']},sort_keys=True)
        compatible.setdefault(key,[]).append(job)
    groups=[]
    for values in compatible.values():
        first=values[0];parallel=min(2,8//first['threads'],first['recorded_concurrency_limit'])
        for offset in range(0,len(values),parallel):
            chunk=values[offset:offset+parallel]
            groups.append(dict(cases=[x['name'] for x in chunk],archived_pin=first['archived_pin'],threads=first['threads'],radial_blocks=first['radial_blocks'],resource_caps=first['resource_caps'],input_capability_receipts=first['input_capability_receipts'],movie_cases=[x['name'] for x in chunk if x['movie']],parallel=min(parallel,len(chunk)),maximum_reserved_CPU_threads=first['threads']*min(parallel,len(chunk))))
    return groups

def group_command(group,force=False,python=sys.executable):
    caps=group['resource_caps']
    argv=[python,'scripts/run_ct_simulations.py',*group['cases'],'--archived-pin',group['archived_pin'],'--threads',str(group['threads']),'--radial-blocks',str(group['radial_blocks']),'--parallel',str(group['parallel']),'--cpu-limit',str(caps['cpu_limit']),'--wall-limit',str(caps['wall_limit']),'--rss-mib',str(caps['rss_mib']),'--as-mib',str(caps['as_mib'])]
    for receipt in group['input_capability_receipts']:argv+=['--input-capability-receipt',receipt]
    if group['movie_cases']:argv+=['--movie-cases',*group['movie_cases']]
    argv+=['--run']
    if force:argv+=['--force']
    return argv

def plan_campaign(root,selection_path,force=False):
    selection=read_json(selection_path);names=selected_names(selection);controller=load_controller(root);metadata=read_json(root/'inputs/metadata.json');cache={}
    jobs=[inspect_case(root,name,controller,metadata,cache) for name in names]
    groups=grouped_jobs(jobs)
    for group in groups:group['command_argv']=group_command(group,force)
    for job in jobs:job['action']='explicit_force_recompute' if force else ('reuse_completed' if job['execution_complete'] else 'requires_explicit_force_for_existing_incomplete_record')
    return dict(mode='read_only_plan',selection_file=str(selection_path),selection_sha256=digest(selection_path),reference_case=selection['reference_case'],animation_case=selection.get('animation_case'),required_case_names=names,force_requested=force,jobs=jobs,sequential_groups=groups,maximum_parallel_jobs=max((g['parallel'] for g in groups),default=0),maximum_reserved_CPU_threads=max((g['maximum_reserved_CPU_threads'] for g in groups),default=0),aggregate_runner_RSS_guard_GiB=3,controller_sha256=digest(root/'scripts/run_ct_simulations.py'),execution_policy='Commands are printed only unless --run. Each group delegates the shared ct_runner.lock, completion reuse, CPU/wall/RSS/process-group caps and full offline archived-byte verification to the qualified controller; groups execute sequentially. No network or original source/tmp reads in planning.')

def products_check(plan):
    if not plan.get('animation_case'):raise ReplayError('Selected CT products require an explicit animation_case')
    for job in plan['jobs']:
        if not job['execution_complete']:raise ReplayError('Selected product case is not completed: '+job['name'])
        if job['name']==plan['animation_case'] and not job['movie']:raise ReplayError('Selected animation case has no recorded ecliptic movie output: '+job['name'])

def execute_groups(plan,root,run=subprocess.run):
    if not plan['force_requested'] and any(not job['execution_complete'] for job in plan['jobs']):raise ReplayError('Existing incomplete case records require explicit --force; completed simulations remain reusable')
    for group in plan['sequential_groups']:
        print('CONTROLLER',json.dumps(group['command_argv']),flush=True)
        run(group['command_argv'],cwd=root,check=True)

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--selection',type=Path,default=ROOT/'results/reference_selection.json');p.add_argument('--run',action='store_true');p.add_argument('--force',action='store_true');p.add_argument('--check-products',action='store_true');p.add_argument('--plan-json',type=Path)
    args=p.parse_args()
    if args.run and args.check_products:p.error('--run and --check-products are separate actions')
    if args.check_products and args.force:p.error('Product validation never recomputes simulations')
    plan=plan_campaign(ROOT,args.selection.resolve(),args.force)
    if args.plan_json:
        args.plan_json.parent.mkdir(parents=True,exist_ok=True);args.plan_json.write_text(json.dumps(plan,indent=2,allow_nan=False)+'\n')
    if args.check_products:
        products_check(plan);print(json.dumps({'selected_completed_CT_cases':plan['required_case_names'],'reference_case':plan['reference_case'],'animation_case':plan['animation_case'],'products_ready':True},indent=2))
    else:
        print(json.dumps(plan,indent=2,allow_nan=False))
        if args.run:execute_groups(plan,ROOT)

if __name__=='__main__':
    try:main()
    except (ReplayError,OSError,KeyError,TypeError,ValueError) as error:raise SystemExit('CT reproduction refused: '+str(error))
